        try {
            List<Callable<Integer>> jobs = new ArrayList<>();
            for (String file : List.of("a.csv", "b.csv", "c.csv")) {
                jobs.add(() -> fake.get(file));      // pretend: count lines
            }
            int total = 0;
            for (Future<Integer> f : pool.invokeAll(jobs)) {
